from starlette.responses import HTMLResponse


def _escape_for_script(data: Any) -> str:
    # Encode as JSON and escape characters that could close or confuse an HTML <script> block
    return (
        json.dumps(data)
        .replace("<", "\\u003c")
        .replace(">", "\\u003e")
        .replace("&", "\\u0026")
    )

